WITH Manager_Scale AS (SELECT t1.PSN_NAME AS manager_name, SUM(t2.NET_VALUE) AS total_scale FROM FUND_AND_MANAGER_MAPPING t1 INNER JOIN FUND_ASSET_ALLOCATION t2 ON t1.FUND_HCODE = t2.FUND_HCODE WHERE t1.PSN_HCODE IN (SELECT PSN_HCODE FROM FUND_MANAGER_INFO WHERE INST_NAME LIKE '%兴证全球%' OR INST_FULL_NAME LIKE '%兴证全球%') AND t1.BEGIN_DATE <= (SELECT MAX(REPORT_DATE) FROM FUND_ASSET_ALLOCATION) AND (t1.END_DATE IS NULL OR t1.END_DATE >= (SELECT MAX(REPORT_DATE) FROM FUND_ASSET_ALLOCATION)) AND t1.HISVALID = 1 AND t2.REPORT_DATE = (SELECT MAX(REPORT_DATE) FROM FUND_ASSET_ALLOCATION) AND t2.HISVALID = 1 AND t2.NET_VALUE IS NOT NULL GROUP BY t1.PSN_NAME) SELECT COUNT(*) AS `规模比谢治宇大的基金经理人数` FROM Manager_Scale WHERE total_scale > (SELECT total_scale FROM Manager_Scale WHERE manager_name = '谢治宇');
200
